INSERT INTO `tournaments` (`id`, `title`, `prize_pool`, `entry_fee`, `rebuy_cost`, `number_of_rebuys`, `duration`, `start_date`, `end_date`, `timezone_label`, `badge_text`, `status`, `is_active`, `description`, `rules`, `prize_distribution`, `sort_order`, `created_at`, `updated_at`) VALUES
(1, 'Crazy Wednesday', 100.00, 10.00, 10.00, 100, '1 day', '2026-09-21 05:00:00', '2026-09-22 05:00:00', 'UTC+05:00', 'Until start: 1 day(s)', 'active', 1, 'Total prize pool is $7500. To participate you need to register and pay the entrance fee, after that $100 will be deposited to a special tournament account. Initial conditions in the tournament are the same for all participants. During one day, participants need to make trades on the tournament account. And 5 traders with the biggest tournament balance will become winners.', NULL, '[{\"place\":\"1 Place\",\"prize\":\"2300$\"},{\"place\":\"2 Place\",\"prize\":\"1800$\"},{\"place\":\"3 Place\",\"prize\":\"1500$\"},{\"place\":\"4 Place\",\"prize\":\"1200$\"},{\"place\":\"5 Place\",\"prize\":\"700$\"}]', 1, '2026-09-20 15:20:33', '2026-11-11 06:07:15'),
(2, 'Free Friday', 300.00, 30.00, 1.00, 50, '1 day', '2026-09-23 05:00:00', '2026-09-24 05:00:00', 'UTC+05:00', 'Until start: 3 day(s)', 'active', 1, 'Free entry tournament with $1,000 guaranteed prize pool for all traders. Test your trading strategies without any risk and win real cash rewards.', NULL, '[{\"place\":\"1 Place\",\"prize\":\"350$\"},{\"place\":\"2 Place\",\"prize\":\"250$\"},{\"place\":\"3 Place\",\"prize\":\"200$\"},{\"place\":\"4 Place\",\"prize\":\"120$\"},{\"place\":\"5 Place\",\"prize\":\"80$\"}]', 2, '2026-09-20 15:20:33', '2026-11-11 06:07:37'),
(3, 'Weekend Battle', 750.00, 100.00, 1.00, 100, '2 days', '2026-09-24 05:00:00', '2026-09-26 05:00:00', 'UTC+05:00', 'Until start: 4 day(s)', 'active', 1, 'Weekend 48-hour trading tournament with huge rewards for top participants. Compete against top traders and claim your share of the $5,000 prize pool.', NULL, '[{\"place\":\"1 Place\",\"prize\":\"1500$\"},{\"place\":\"2 Place\",\"prize\":\"1200$\"},{\"place\":\"3 Place\",\"prize\":\"1000$\"},{\"place\":\"4 Place\",\"prize\":\"800$\"},{\"place\":\"5 Place\",\"prize\":\"500$\"}]', 3, '2026-09-20 15:20:33', '2026-11-11 06:08:26'),
(4, 'Grand 100K Championship', 1500.00, 200.00, 50.00, 200, '30 days', '2026-08-21 05:00:00', '2026-09-19 05:00:00', 'UTC+05:00', 'Completed', 'completed', 1, 'Annual grand championship for professional binary traders with massive $100,000 prize pool distribution.', NULL, '[{\"place\":\"1 Place\",\"prize\":\"30000$\"},{\"place\":\"2 Place\",\"prize\":\"25000$\"},{\"place\":\"3 Place\",\"prize\":\"20000$\"},{\"place\":\"4 Place\",\"prize\":\"15000$\"},{\"place\":\"5 Place\",\"prize\":\"10000$\"}]', 4, '2026-09-20 15:20:33', '2026-11-11 06:09:19');
